package com.oms.supplychain.service.wms;

import org.springframework.stereotype.Service;
import javax.annotation.Resource;
import java.util.*;
import static com.oms.supplychain.service.wms.WmsStore.*;

/** Purchase -> arrival -> accepted warehouse quantities -> posted stock, without advancing anything. */
@Service public class ProcurementJourney {
    @Resource WmsStore db;
    @Resource WarehouseInteractionSummary interactions;
    private static String marks(Collection<?> values){return String.join(",",Collections.nCopies(values.size(),"?"));}
    private static long n(Object value){return value==null?0:id(value);}
    private List<Object> args(String c,Collection<?> values){List<Object> a=new ArrayList<>();a.add(c);a.addAll(values);return a;}
    static Map<String,Object> camel(Map<String,Object> raw){Map<String,Object> out=new LinkedHashMap<>();for(Map.Entry<String,Object> e:raw.entrySet()){StringBuilder key=new StringBuilder();boolean upper=false;for(char ch:e.getKey().toCharArray())if(ch=='_')upper=true;else{key.append(upper?Character.toUpperCase(ch):ch);upper=false;}out.put(key.toString(),e.getValue());}ReturnQueryWarehouse.formatTimes(out);return out;}
    public List<Map<String,Object>> tickets(String c,String kind,long key){return tickets(c,kind,Collections.singletonList(key));}
    private List<Map<String,Object>> tickets(String c,String kind,List<Long> keys){
        String condition=("purchase".equals(kind)?"p.id":"n.id")+" IN ("+marks(keys)+")";
        List<Map<String,Object>> records=db.jdbc.queryForList("SELECT t.*,a.id inbound_task_id,a.dispatch_state,a.cancel_state,a.receipt_state,a.external_order,a.warehouse_status,a.last_error,c.provider,n.id receipt_id,n.no_sn receipt_sn,p.id purchase_id,s.supplier_name,v.wms_simulation_name warehouse_name,o.owner_name,w.wms_name real_warehouse_name FROM po_info p JOIN no_tickets n ON n.company_key=p.company_key AND n.po_sn=p.po_sn JOIN wms_tickets t ON t.company_key=n.company_key AND t.relation_sn=n.no_sn LEFT JOIN wms_inbound_task a ON a.company_code=t.company_key AND a.ticket_id=t.id LEFT JOIN wms_connection c ON c.company_code=a.company_code AND c.id=a.connection_id LEFT JOIN supplier_info s ON s.company_key=p.company_key AND s.supplier_sn=p.supplier_sn LEFT JOIN wms_simulation_store_info v ON v.company_key=t.company_key AND v.wms_simulation_code=t.wms_simulation_code LEFT JOIN owner_warehouse ow ON ow.id=v.owner_warehouse_id AND ow.company_key=v.company_key LEFT JOIN owner_info o ON o.id=ow.owner_id AND o.company_key=ow.company_key LEFT JOIN wms_real_store_info w ON w.id=ow.real_store_id AND w.company_key=ow.company_key WHERE p.company_key=? AND "+condition+" ORDER BY t.id DESC LIMIT 501",args(c,keys).toArray());
        require(records.size()<=500,"关联入库单超过500张，请按到货单查看");List<Map<String,Object>> out=new ArrayList<>();for(Map<String,Object> raw:records)out.add(camel(raw));if(out.isEmpty())return out;
        List<String> sns=new ArrayList<>();Set<Long> taskIds=new LinkedHashSet<>();for(Map<String,Object> t:out){sns.add(text(t.get("sn")));if(t.get("inboundTaskId")!=null)taskIds.add(n(t.get("inboundTaskId")));}
        Map<String,List<Map<String,Object>>> lines=new HashMap<>();for(Map<String,Object> g:db.jdbc.queryForList("SELECT * FROM wms_tickets_goods WHERE company_code=? AND sn IN ("+marks(sns)+") ORDER BY id",args(c,sns).toArray()))lines.computeIfAbsent(text(g.get("sn")),k->new ArrayList<>()).add(camel(g));
        Map<Long,Long> postedByLine=new HashMap<>();if(!taskIds.isEmpty())for(Map<String,Object> line:db.jdbc.queryForList("SELECT ticket_line_id,SUM(IF(posted=1,good_qty+bad_qty,0)) posted FROM wms_receipt_line WHERE company_code=? AND task_id IN ("+marks(taskIds)+") GROUP BY ticket_line_id",args(c,taskIds).toArray()))postedByLine.put(n(line.get("ticket_line_id")),n(line.get("posted")));
        for(Map<String,Object> t:out){List<Map<String,Object>> goods=lines.getOrDefault(text(t.get("sn")),Collections.emptyList());long plan=0,actual=0,posted=0,bad=0;for(Map<String,Object> g:goods){long qty=n(g.get("numberActually")),p=t.get("inboundTaskId")!=null?postedByLine.getOrDefault(n(g.get("id")),0L):n(g.get("inventoryIsHandle"))==2?qty:0;g.put("numberPosted",p);plan+=n(g.get("numberExpected"));actual+=qty;posted+=p;bad+=n(g.get("numberCp"));}boolean end="COMPLETE".equals(t.get("receiptState"))||"CONFIRMED".equals(t.get("cancelState"))||n(t.get("actualWarehouse"))==2&&n(t.get("statusTicket"))==2;String progress="COMPLETED".equals(t.get("cutoffState"))&&n(t.get("cancelledQuantity"))>0&&actual>0?"CLOSED":n(t.get("statusTicket"))==5?"CANCELED":n(t.get("inventoryStatus"))==3||Arrays.asList("FAILED","UNKNOWN").contains(text(t.get("dispatchState")))?"ATTENTION":end&&actual==posted?"COMPLETE":"PROCESSING";t.putAll(map("documentType","PURCHASE_IN","numberExpected",plan,"numberActually",actual,"numberPosted",posted,"badQuantity",bad,"receiptFinal",end?1:0,"progress",progress,"postingState",n(t.get("inventoryStatus"))==3?"ERROR":posted==actual&&actual>0?"POSTED":posted>0?"PARTIAL":"NOT_STARTED","businessUpdatedTime",t.get("modifyTime"),"lines",goods));TicketPresentation.present(t);}
        interactions.attach(c,out);return out;
    }
    public void attachPage(String c,String kind,List<Map<String,Object>> rows){if(rows.isEmpty())return;List<Long> ids=new ArrayList<>();for(Map<String,Object> r:rows)ids.add(n(r.get("id")));List<Map<String,Object>> tickets=tickets(c,kind,ids);for(Map<String,Object> row:rows){List<Map<String,Object>> own=new ArrayList<>();for(Map<String,Object> t:tickets)if(n(t.get("purchase".equals(kind)?"purchaseId":"receiptId"))==n(row.get("id")))own.add(t);row.put("warehouseExecutions",own);row.put("confirmedQuantity",own.stream().mapToLong(t->n(t.get("numberActually"))).sum());row.put("postedQuantity",own.stream().mapToLong(t->n(t.get("numberPosted"))).sum());}}
    @SuppressWarnings("unchecked") public void enrich(String c,String kind,Map<String,Object> document){
        List<Map<String,Object>> tickets=tickets(c,kind,n(document.get("id")));document.put("tickets",tickets);Map<String,Map<String,Long>> totals=new HashMap<>();Map<String,Object> summary=map("planned",n(document.get("numberExpected")),"confirmed",0L,"posted",0L,"bad",0L,"short",0L,"cancelled",0L,"unreceived",0L,"unarranged",0L,"scheduled",0L);
        for(Map<String,Object> t:tickets){boolean end=Boolean.TRUE.equals(t.get("receiptFinal"))||n(t.get("receiptFinal"))==1;for(Map<String,Object> g:(List<Map<String,Object>>)t.get("lines")){Map<String,Long> agg=totals.computeIfAbsent(text(g.get("skuSn")),k->new HashMap<>());for(String[] pair:new String[][]{{"confirmed","numberActually"},{"posted","numberPosted"},{"bad","numberCp"},{"cancelled","cancelledQuantity"}})agg.merge(pair[0],n(g.get(pair[1])),Long::sum);long remaining=Math.max(0,n(g.get("numberExpected"))-n(g.get("numberActually"))-n(g.get("cancelledQuantity")));agg.merge(end?"short":"unreceived",remaining,Long::sum);}}
        List<Map<String,Object>> pending=db.jdbc.queryForList("SELECT g.sku_sn,SUM(g.zp_number_expected+g.cp_number_expected) quantity FROM no_tickets n JOIN no_tickets_goods g ON g.company_code=n.company_key AND g.no_sn=n.no_sn WHERE n.company_key=? AND "+("purchase".equals(kind)?"n.po_sn=?":"n.no_sn=?")+" AND n.no_state IN(1,2) AND COALESCE(n.relation_sn,'')='' GROUP BY g.sku_sn",c,document.get("purchase".equals(kind)?"poSn":"noSn"));for(Map<String,Object> p:pending)totals.computeIfAbsent(text(p.get("sku_sn")),k->new HashMap<>()).merge("unreceived",n(p.get("quantity")),Long::sum);
        if("receipt".equals(kind)){Map<String,Object> parent=db.one("SELECT p.id,s.supplier_name FROM po_info p LEFT JOIN supplier_info s ON s.company_key=p.company_key AND s.supplier_sn=p.supplier_sn WHERE p.company_key=? AND p.po_sn=?",c,document.get("poSn"));document.put("purchaseId",parent.get("id"));document.put("supplierName",parent.get("supplier_name"));}
        Map<String,String> units=new HashMap<>();for(Map<String,Object> l:db.jdbc.queryForList("SELECT sku_sn,stock_unit FROM purchase_line WHERE company_code=? AND po_sn=?",c,document.get("poSn")))units.put(text(l.get("sku_sn")),text(l.get("stock_unit")));Map<String,Map<String,Object>> unitTotals=new LinkedHashMap<>();
        for(Map<String,Object> l:(List<Map<String,Object>>)document.get("lines")){String sku=text(l.get("skuSn"));Map<String,Long> a=totals.getOrDefault(sku,Collections.emptyMap());for(String key:Arrays.asList("confirmed","posted","bad","short","cancelled","unreceived")){long value=a.getOrDefault(key,0L);l.put(key+"Quantity",value);summary.put(key,n(summary.get(key))+value);}if("purchase".equals(kind)){long unscheduled=Math.max(0,n(l.get("quantity"))-n(l.get("scheduledQuantity")));l.put("unarrangedQuantity",unscheduled);summary.put("unarranged",n(summary.get("unarranged"))+unscheduled);summary.put("scheduled",n(summary.get("scheduled"))+n(l.get("scheduledQuantity")));}l.put("unpostedQuantity",Math.max(0,n(l.get("confirmedQuantity"))-n(l.get("postedQuantity"))));String unit=units.getOrDefault(sku,"件");l.put("stockUnit",unit);Map<String,Object> u=unitTotals.computeIfAbsent(unit,k->map("unit",k));long planned="purchase".equals(kind)?n(l.get("quantity")):n(l.get("zpNumberExpected"))+n(l.get("cpNumberExpected"));u.put("planned",n(u.get("planned"))+planned);for(String k:Arrays.asList("confirmed","posted","bad","short","cancelled","unreceived","unarranged","scheduled","unposted"))u.put(k,n(u.get(k))+n(l.get(k+"Quantity")));}summary.put("units",new ArrayList<>(unitTotals.values()));
        summary.put("unposted",Math.max(0,n(summary.get("confirmed"))-n(summary.get("posted"))));document.put("journey",summary);
        if("purchase".equals(kind)){List<Map<String,Object>> receipts=(List<Map<String,Object>>)document.get("receipts");for(Map<String,Object> r:receipts){List<Map<String,Object>> own=new ArrayList<>();for(Map<String,Object> t:tickets)if(n(t.get("receiptId"))==n(r.get("id")))own.add(t);r.put("executions",own);}}
    }
}
